n("קמר", "קמר היא המילה הערבית לירח, ובשירה הערבית הירח המלא הוא תמונה מוכרת של יופי ושל אור בלילה. הלוח המוסלמי הוא לוח ירחי, ובו כל חודש מתחיל כשנראה הירח החדש. בעברית הירח נקרא בשם אחר, ירח או לבנה.")
n("דני", "דני היא צורת חיבה של דניאל, שם שמחבר את הפועל דן, שפט, עם שם האל, ופירושו אלוהים הוא השופט שלי. דני התחיל, כמו הרבה שמות אחרים, ככינוי של חיבה ועם הזמן נעשה שם בפני עצמו. מאותו שורש, ד־י־נ, באות המילים דין, דיין ובית דין.", ["דניאל"])
n("טום", "טום הוא הצורה הקצרה של תומאס, שם שבא מהמילה הארמית תאומא, תאום. השם עבר ליוונית וללטינית, ומשם לשפות רבות באירופה, ובאנגלית טום וטומי הם הצורות הקצרות שלו. בעברית אפשר לשמוע בו גם את המילה תום, יושר ושלמות.", ["טומי", "תומאס"])
n("פארס", "פארס היא מילה ערבית לפרש, רוכב סוסים, ובהשאלה גם אדם אמיץ ואציל. מאותו שורש באה בערבית המילה פרס, סוס, וגם בעברית יש מילה קרובה, פרש. בשירה הערבית הפרש הוא דמות מוכרת של אומץ ושל נאמנות.")
n("שפרה", "שפרה באה מהשורש ש־פ־ר, שעניינו יופי וטוב, ומאותו שורש באות גם המילים שפיר ושיפור. בתורה שפרה ופועה הן המיילדות במצרים, שלא צייתו לפרעה ושמרו על חיי התינוקות. בעברית של היום המילה שפר מוכרת בצירוף שפר עליו גורלו.")
n("בת", "בת היא ילדה של אב ושל אם, והמילה מוכרת כבר מהעברית העתיקה. בעברית היא משמשת גם בצירופים רבים, כמו בת קול, בת צחוק ובת ים, ובשמות כמו בתיה ובת שבע. כשם, בת עומדת לבדה, בלי מילה נוספת אחריה.")
n("מרום", "מרום הוא גובה, מקום גבוה מאוד, וגם השמיים. בספר ישעיהו המילה מופיעה בתיאור של המקום הגבוה והקדוש שבו שוכן האל. מאותו שורש, ר־ו־מ, באות גם המילים רם, רוממות ותרומה. השם ניתן לבנים ולבנות.")
n("אלמוג", "אלמוג הוא יצור ימי קטן שחי במושבות גדולות, ומהשלד שלו נבנות שוניות צבעוניות במים חמים. בארץ שוניות האלמוגים מוכרות במפרץ אילת. אלמוג אדום שימש מימים קדומים לתכשיטים. השם ניתן לבנים ולבנות.")
n("דורי", "דורי פירושו הדור שלי, והשם בנוי על המילה דור, כל האנשים שחיים באותו זמן, עם סיומת של שייכות. בעברית המילה מוכרת בצירופים כמו מדור לדור ובני דורי. מאותה מילה נבנו גם השמות דור ודוראל.", ["דור", "דוראל"])
n("יאן", "יאן הוא הצורה של השם יוחנן בכמה שפות באירופה, כמו הולנדית, צ׳כית ופולנית. השם עבר מעברית ליוונית וללטינית, ובכל שפה קיבל צורה משלו. בצורתו העברית יוחנן מחבר את יו, קיצור של שם ה׳, עם חנן, ופירושו ה׳ חנן.", ["יוחנן"])
n("יפה", "יפה מתארת דבר שנעים לראות ולשמוע, והמילה מוכרת כבר מהעברית העתיקה. בשיר השירים המילה חוזרת שוב ושוב בדברים שהאוהבים אומרים זה לזה. מאותה מילה באות גם יופי והתייפות, ונבנה ממנה גם השם יפית.", ["יפית"])
n("רנה", "רנה היא כתיב חסר של רינה, שיר ושמחה. מאותו שורש, ר־נ־ן, באות גם המילים רון ורננה, ובעברית הן מתארות לרוב שירה בקול של שמחה. מאותה מילה נבנו גם רון, רוני, רני ורונה.", ["רינה", "רון", "רוני", "רני", "רונה"])
n("ביסאן", "ביסאן הוא השם הערבי של בית שאן, עיר עתיקה בעמק שבין הגלבוע לנהר הירדן. בתל של העיר ובסביבתו נחשפו שרידים של תקופות רבות, ובהם רחובות ותיאטרון מימי הרומאים. השם הערבי שמר צורה קרובה לשם העתיק, כמו שקרה לשמות מקומות רבים בארץ.")
n("סיני", "סיני הוא חצי אי מדברי בין מצרים לארץ ישראל, עם הרים גבוהים וחוף ארוך לים. לפי התורה, על הר סיני ניתנו התורה ועשרת הדיברות, ובמדבר סיני חנו בני ישראל בדרכם ממצרים. מקור השם אינו ודאי, ויש שקשרו אותו לשיח הסנה.")
n("רואי", "רואי פירושו הרואה אותי, והשם בנוי על השורש ר־א־ה. בתורה הגר, שפחתה של שרי, בורחת למדבר, ושם היא קוראת לבאר בשם באר לחי רואי, הבאר של מי שרואה אותי. מאותו שורש באות גם המילים ראייה ומראה.")
n("ג'ואד", "ג'ואד היא מילה ערבית שפירושה נדיב, מי שנותן ביד רחבה. מאותו שורש, ג׳־ו־ד, באות בערבית גם המילים ג'ודה, טוב ואיכות. השם נכתב בעברית גם ג'וואד, עם שתי אותיות ו.", ["ג'וואד"])
n("סולטאן", "סולטאן היא מילה ערבית שפירושה שלטון וכוח, ומכאן גם תואר של שליט. מאותו שורש באה בערבית המילה סלטה, סמכות, והמילה עברה לשפות רבות, גם לעברית, בצורה סולטן. השם נכתב בעברית גם סלטאן.", ["סלטאן"])
n("חוסין", "חוסין הוא צורת הקטנה של חסן, ופירושו טוב ונאה. השניים באים מהשורש הערבי ח־ס־נ, שממנו באות גם המילים חסן, יפה, ואחסאן, מעשה טוב. בערבית יש שמות רבים שבנויים כצורת הקטנה של שם אחר, והם נחשבים לשמות נפרדים.")
n("סלמא", "סלמא היא מילה ערבית שפירושה שלמה ושלווה, מהשורש ס־ל־מ, שהוא גם השורש העברי של המילים שלום ושלמות. השם מוכר בערבית מתקופה עתיקה, וגם בשירה הערבית הקלאסית. כך שתי השפות, שהן שפות שמיות קרובות, חולקות כאן שורש ומשמעות.")
n("איילת", "איילת היא צורה של המילה איילה, והיא מוכרת בעיקר בצירוף איילת השחר, הכוכב הבהיר שנראה לפני הזריחה. בספר תהילים אחד המזמורים נפתח במילים על איילת השחר. אילת היא כתיב אחר של אותו שם, ואייל ואיילה בנויים על אותה מילה.", ["איילה", "אייל", "אילת"])
n("יאסין", "יאסין הוא שמה של סורה בקוראן, שנקראת על שם שתי האותיות הערביות שבהן היא נפתחת, יא וסין. בקוראן יש כמה סורות שנפתחות באותיות בודדות, ומשמעות האותיות האלה אינה ידועה בוודאות. משם עבר יאסין לשמש גם כשם פרטי.")
n("יותם", "השם מחבר את יו, קיצור של שם ה׳, עם תם, שלם וישר, ופירושו ה׳ הוא שלם. בספר שופטים יותם הוא הבן הצעיר של גדעון, היחיד מאחיו שניצל, והוא נושא משל על העצים שמחפשים להם מלך. מאותו שורש, ת־מ־מ, באות גם המילים תום ותמים.")
n("רננה", "רננה היא שירה בקול של שמחה, מהשורש ר־נ־ן, שממנו באות גם המילים רינה ורון. בספר תהילים המילה מופיעה בקריאה לבוא לפני ה׳ ברננה. מאותה מילה נבנה גם השם רנן.", ["רנן"])
n("ליית", "ליית היא אחת המילים הערביות לאריה, ובערבית יש לאריה שמות רבים. מאותו מקור באה גם המילה העברית ליש, שמופיעה בעברית העתיקה כשם של אריה. בשירה הערבית האריה הוא תמונה מוכרת של אומץ ושל כוח.")
n("סאמי", "סאמי היא מילה ערבית שפירושה נעלה ורם, מי שעומד במקום גבוה. היא באה מהשורש ס־מ־ו, שעניינו גובה, ומאותו שורש באה בערבית גם המילה סמא, שמיים. סאמיה היא הצורה הנשית של השם.", ["סאמיה"])
n("אדיר", "אדיר הוא חזק, גדול ומפואר, מהשורש א־ד־ר, שממנו באות גם המילים אדרת ואדירות. בספר תהילים המילה מופיעה בשבח לשם ה׳, שהוא אדיר בכל הארץ. בעברית של היום אדיר משמש גם במשמעות של נפלא, למשל ביום אדיר.")
n("אלאור", "אלאור מחבר את המילה אל עם אור, ופירושו אלוהים הוא אור. באותה דרך נבנו שמות עבריים רבים שנפתחים ב־אל או ב־אלי, כמו אליאור, שפירושו כמעט אותו דבר. מאותה מילה, אור, נבנו גם אורי, אורה ואוריאל.", ["אליאור"])
n("גיל", "גיל היא שמחה, ובעברית המקראית המילה מופיעה לרוב לצד שמחה, ששון ורינה. בספר תהילים המשורר מתאר את האל כמקור לשמחה ולגיל שלו. מאותה מילה בא גם הפועל לגיל, ונבנו גם השמות גילי וגילה. השם ניתן לבנים ולבנות.", ["גילי", "גילה"])
n("וליד", "וליד היא מילה ערבית שפירושה יילוד, תינוק שזה עתה נולד. היא באה מהשורש ו־ל־ד, שהוא גם השורש העברי של המילים ילד, לידה ומולדת. כך שתי השפות, שהן שפות שמיות קרובות, חולקות כאן שורש ומשמעות.")
n("נרי", "נרי פירושו הנר שלי, והשם בנוי על המילה נר, עם סיומת של שייכות. בספר תהילים המשורר אומר לאל שהוא מאיר את נרו, כלומר מאיר את דרכו בחושך. מאותה מילה נבנה גם השם נריה, הנר של ה׳. השם ניתן לבנים ולבנות.", ["נריה"])
n("עדיה", "עדיה מחבר את המילה עדי, תכשיט, עם יה, קיצור של שם ה׳, ופירושו התכשיט של ה׳. בעברית המקראית עדי הוא קישוט ותכשיט, ומאותו שורש בא גם הפועל לעדות, להתקשט. מאותה מילה נבנו גם השמות עדי ועדיאל.", ["עדי", "עדיאל"])
n("עילי", "עילי פירושו עליון, והשם בא מהשורש ע־ל־ה, שממנו באות גם המילים עלייה, עליון ומעלה. בעברית של היום עילי מתאר דבר שנמצא למעלה, כמו בצירוף הגליל העילי, וגם דבר מעולה ונעלה. מאותה מילה בא גם התואר עילאי.")
n("אלונה", "אלונה בנוי על המילה אלון, עץ חזק ועתיק, ששורשיו עמוקים והוא חי שנים רבות. בחורש הים תיכוני בארץ האלון הוא אחד העצים המוכרים, ובגליל ובכרמל יש אלונים עתיקים. אלון הוא הצורה של השם בלשון זכר.", ["אלון"])
n("דינה", "דינה באה מהמילה דין, משפט, והשם קרוב לשמות דן ודניאל, שבנויים על אותו שורש. בתורה דינה היא בתם של יעקב ולאה, והיא מוזכרת בסיפור של בני יעקב בשכם. מאותו שורש, ד־י־נ, באות גם המילים דיין ובית דין.", ["דין"])
n("ח'ליל", "ח'ליל היא מילה ערבית לחבר קרוב, ידיד נאמן. בערבית אברהם נקרא ח'ליל אללה, ידיד האל, ומכאן גם השם הערבי של העיר חברון, אל־ח'ליל, העיר של אברהם.")
n("ראובן", "ראובן מחבר את המילים ראו ובן, ופירושו ראו, בן. בתורה ראובן הוא הבכור של יעקב ולאה, ולאה קוראת לו כך כשהוא נולד. ראובן הוא גם שמו של אחד משבטי ישראל, שנחלתו הייתה ממזרח לנהר הירדן.")
n("שיראל", "שיראל מחבר את המילה שיר עם אל, ופירושו שיר לאלוהים. באותה דרך נבנו שמות עבריים רבים שנגמרים ב־אל, כמו אוראל ואריאל. מאותה מילה נבנו גם שיר, שירה ושירי.", ["שיר", "שירה", "שירי"])
n("שיינדל", "שיינדל בא מהמילה היידית שיין, יפה, עם סיומת של חיבה, ופירושו יפה קטנה. בקהילות אשכנז נבנו כך שמות רבים ממילים ביידיש, לצד השמות העבריים. שיינא היא צורה של אותו שם, ושינדל הוא כתיב אחר שלו.", ["שיינא", "שינדל"])
n("ענר", "ענר הוא שם מקראי עתיק, ומשמעותו אינה ידועה בוודאות. בספר בראשית ענר, אשכול וממרא הם בני בריתו של אברם, שיוצאים איתו להציל את לוט, בן אחיו. בעברית השם קצר, ונכתב בשלוש אותיות בלבד.")
n("סאלם", "סאלם היא מילה ערבית שפירושה שלם ובטוח, מי שיצא בשלום מסכנה. היא באה מהשורש ס־ל־מ, שהוא גם השורש העברי של המילים שלום, שלם ושלמות. בערבית מאותו שורש באים גם השמות סלים וסלמא.")
n("אילן", "אילן הוא עץ, ובעיקר עץ גדול. המילה באה מהארמית, ובתנ״ך היא מופיעה בספר דניאל, בחלום על עץ גבוה מאוד באמצע הארץ. בעברית של היום מוכר הצירוף אילן יוחסין, עץ המשפחה. אילנה היא הצורה הנשית של השם.", ["אילנה"])
n("עטרה", "עטרה היא כתר, וגם זר שעונדים על הראש. בעברית המקראית המילה משמשת לרוב בהשאלה, למשל במשלי, שם אשת חיל היא עטרת בעלה. בספר דברי הימים עטרה היא אחת הנשים בשבט יהודה. עטרת היא צורה של אותו שם.", ["עטרת"])
n("עמראן", "עמראן הוא הצורה הערבית של השם עמרם, אביהם של משה, אהרן ומרים. בערבית השם מוכר גם בגלל משפחת עמראן, שעל שמה נקראת אחת מסורות הקוראן. השם נכתב בעברית גם עומראן.", ["עמרם", "עומראן"])
n("תפארת", "תפארת היא יופי, הדר וכבוד, מהשורש פ־א־ר, שממנו באות גם המילים פאר ומפואר. בספר ישעיהו המילה מופיעה בצירוף עטרת תפארת, כתר יפה, בתיאור של ירושלים. בעברית של היום מוכר גם הצירוף לתפארת, כלומר בצורה יפה ומוצלחת.")
n("אהובה", "אהובה היא מי שאוהבים אותה, מהשורש א־ה־ב, שממנו באות גם המילים אהבה, אוהב ואהוב. בעברית המקראית המילה מופיעה בעיקר בשירה, ובעברית של היום היא מוכרת גם כפנייה של חיבה. מאותה מילה נבנה גם השם אהוביה.", ["אהוביה"])
n("אלישע", "השם מחבר את המילה אלי עם שע, ישועה, ופירושו אלוהיי הוא ישועה. בספר מלכים אלישע בן שפט הוא תלמידו של אליהו הנביא, שפוגש אותו כשהוא חורש בשדה, ואחריו הוא ממשיך את דרכו. מאותו שורש, י־ש־ע, באים גם השמות יהושע וישעיהו.")
n("ניר", "ניר הוא שדה חרוש, אדמה שהופכים אותה כדי להכין אותה לזריעה. בספר ירמיהו המילה מופיעה בקריאה לחרוש ניר, כלומר להתחיל מחדש. בעברית של היום המילה מוכרת גם בשמות של יישובים רבים, כמו ניר עם וניר עוז. נירי בנוי על אותה מילה.", ["נירי"])
n("סעיד", "סעיד היא מילה ערבית שפירושה מאושר ומבורך. היא באה מהשורש ס־ע־ד, שעניינו אושר והצלחה, ומאותו שורש באים בערבית גם השמות סעד וסעוד, וגם המילה סעאדה, אושר. השם מוכר בכל העולם הערבי.")

